<script lang="ts">
 import {onMount} from 'svelte';
 import {invalidateAll} from '$app/navigation';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 import type {CommunityGateway} from '../application/community';
 let {titleId,titleSlug,score,ratingCount,gateway}:{titleId:string;titleSlug:string;score:number;ratingCount:number;gateway:CommunityGateway}=$props();
 const {locale}=useLocale();
 const bright=['#ff737c','#ff8869','#f59b58','#e9ad51','#d8ba51','#bdc85b','#9ad16d','#78d482','#5bd398','#48cfa6'];
 const phrases=$derived($locale==='ru'?['Выбери впечатление','Совсем не понравилось','Слабое впечатление','Много недостатков','Не зацепило','Средне','Неплохо','Хорошая работа','Очень понравилось','Почти идеально','Один из любимых']:['Әсеріңді бағала','Мүлде ұнамады','Әсері әлсіз','Кемшілігі көп','Қызықтырмады','Орташа','Жаман емес','Жақсы жұмыс','Қатты ұнады','Мінсізге жақын','Сүйіктілерімнің бірі']);
 let preview=$state<number|null>(null);
 const colors=['#a52a36','#a1362b','#95401f','#87491b','#77531a','#655b1a','#4e621e','#34672c','#20683c','#176648'];
 let dialog:HTMLDialogElement|undefined;
 let account=$state<string|null>(null),value=$state(0),busy=$state(true),error=$state('');
 const shown=$derived(preview??value);
 let generation=0,alive=false;
 async function load(){const token=++generation;busy=true;error='';try{const actor=await gateway.account();const rating=actor?await gateway.myRating(actor,titleId):0;if(alive&&token===generation){account=actor;value=rating;}}catch(failure){if(alive&&token===generation)error=failureCode(failure);}finally{if(alive&&token===generation)busy=false;}}
 onMount(()=>{alive=true;void load();return()=>{alive=false;generation++;};});
 function open(){preview=null;dialog?.showModal();if(!busy)void load();}
 async function save(next:number){if(!account||busy)return;busy=true;error='';preview=next;try{await gateway.rating(account,titleId,next);if(!alive)return;value=next;preview=null;await invalidateAll();dialog?.close();}catch(failure){if(alive){preview=null;error=failureCode(failure);}}finally{if(alive)busy=false;}}
</script>
<button class="rating-trigger" type="button" onclick={open} aria-label={text($locale,'Тайтлды бағалау','Оценить тайтл')}><strong>{ratingCount>0?score.toFixed(2):'—'}</strong><span>{ratingCount} {text($locale,'баға','оценок')}</span><span class="rate-label">{value>0?text($locale,'Бағаң: ','Ваша: ')+value:text($locale,'Бағалау','Оценить')}</span></button>
<dialog bind:this={dialog} style:--rating-dim={shown>0?colors[shown-1]:undefined} style:--rating-bright={shown>0?bright[shown-1]:undefined} class="rating-dialog" aria-labelledby="rating-title"><div class="dialog-head"><h2 id="rating-title">{text($locale,'Тайтлды бағалау','Оценить тайтл')}</h2><button class="button subtle" type="button" onclick={()=>dialog?.close()} aria-label={text($locale,'Жабу','Закрыть')}>×</button></div>{#if busy}<p role="status">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}{#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if account}<div class="rating-preview" aria-live="polite"><strong class="rating-number">{shown}</strong><p class="rating-phrase">{phrases[shown]}</p></div><div class="rating-choices" role="group" aria-label={text($locale,'Сіздің бағаңыз','Ваша оценка')}>{#each colors as color,index}<button class="rating-choice" type="button" aria-label={index+1+' / 10'} aria-pressed={value===index+1} disabled={busy} onpointerenter={()=>preview=index+1} onpointerleave={()=>preview=null} onfocus={()=>preview=index+1} onblur={()=>preview=null} onclick={()=>save(index+1)}><svg aria-hidden="true" viewBox="0 0 24 24" class:filled={index<shown}><path d="M12 1C13.5 8.5 15.5 10.5 23 12C15.5 13.5 13.5 15.5 12 23C10.5 15.5 8.5 13.5 1 12C8.5 10.5 10.5 8.5 12 1Z"/></svg></button>{/each}</div><div class="rating-footer"><button class="later" type="button" disabled={busy} onclick={()=>dialog?.close()}>{text($locale,'Кейінірек','Позже')}</button>{#if value>0}<button class="remove-rating" type="button" disabled={busy} onclick={()=>save(0)}>{text($locale,'Бағаны алып тастау','Удалить оценку')}</button>{/if}</div>{:else if !busy&&!error}<p>{text($locale,'Бағалау үшін жүйеге кіріңіз.','Войдите, чтобы оценить тайтл.')}</p><a class="button primary" href={'/login?returnTo='+encodeURIComponent('/titles/'+titleSlug)}>{text($locale,'Кіру','Войти')}</a>{/if}</dialog>
<style>
 .rating-trigger{display:flex;align-items:center;text-decoration:none;flex-direction:column;font-size:12px;color:var(--muted);min-height:44px;flex:none;border:0;background:none;cursor:pointer}.rating-trigger strong{color:var(--accent);font-size:21px;line-height:1.3}.rate-label{margin-top:4px;padding:6px 10px;border-radius:6px;background:var(--panel);color:var(--text)}.rating-dialog{width:min(560px,calc(100vw - 24px));padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);box-shadow:0 24px 72px #0008}.rating-dialog::backdrop{background:#0009}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.dialog-head h2{font-size:19px;margin:0}.dialog-head button{min-width:44px;font-size:23px}.rating-preview{text-align:center;margin:16px 0 4px;color:var(--rating-ink,var(--muted))}.rating-number{font-size:42px;line-height:1.2;font-weight:750}.rating-phrase{font-size:19px;font-weight:650;min-height:50px;display:grid;place-items:center;margin:10px 0 0;line-height:1.3}.rating-dialog{--rating-ink:var(--rating-dim,var(--muted))}.rating-choices{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:clamp(2px,.8vw,6px);padding:4px 0;margin-top:12px}.rating-choice{display:flex;align-items:center;justify-content:center;min-width:0;width:100%;height:44px;padding:0;background:none;border:0;cursor:pointer}.rating-choice svg{transition:fill 180ms ease,transform 120ms ease;display:block;width:100%;max-width:32px;aspect-ratio:1;fill:var(--muted)}.rating-choice:not(:disabled):is(:hover,:focus-visible) svg{transform:scale(1.08)}.rating-preview{transition:color 180ms ease}.rating-choice svg.filled{fill:var(--rating-ink)}.rating-choice[aria-pressed='true']{outline:1px solid var(--line);outline-offset:-2px;border-radius:6px}.rating-choice:focus-visible{outline:2px solid var(--text);outline-offset:2px;border-radius:6px}.rating-choice:disabled{cursor:wait}.rating-footer{display:flex;gap:8px;margin-top:12px}.later,.remove-rating{flex:1;min-height:44px;border:1px solid var(--line);border-radius:8px;background:var(--raised);color:var(--text);cursor:pointer;font:inherit;font-size:13px;padding:8px}.remove-rating{background:none;color:var(--muted)}:global(:root[data-theme='dark']) .rating-dialog{--rating-ink:var(--rating-bright,var(--muted))}@media(prefers-color-scheme:dark){:global(:root:not([data-theme])) .rating-dialog{--rating-ink:var(--rating-bright,var(--muted))}}

@media(prefers-reduced-motion:reduce){.rating-choice svg{transform:none!important}}:global(html[data-motion=reduce]) .rating-choice svg{transform:none!important}</style>
